请对以下 case 进行三维加权评分。

=== case_id ===
Case-06-memory-clean-001

=== 用户原始指令 (query.txt) ===
帮我弄个内存清理,要看到比例,显示一行数字说清了多少,点一下能跳到应用,能读日历,不够用提醒我

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我弄个内存清理,要看到比例,显示一行数字说清了多少,点一下能跳到应用,能读日历,不够用提醒我",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "storage_settings"
      }
    }
  ],
  "dataModelSchema": {
    "memory": {
      "usagePercent": {
        "type": "number",
        "description": "当前内存或存储占用比例，用于展示比例进度。",
        "sampleValue": 82
      },
      "progressTotal": {
        "type": "number",
        "description": "比例进度的总量基准。",
        "sampleValue": 100
      },
      "cleanedText": {
        "type": "string",
        "description": "最近一次清理释放的容量展示文本。",
        "sampleValue": "已清理 1.8GB"
      },
      "availableText": {
        "type": "string",
        "description": "当前剩余可用容量展示文本。",
        "sampleValue": "剩余 3.2GB"
      },
      "warningText": {
        "type": "string",
        "description": "空间或内存不够用时的提醒文案。",
        "sampleValue": "可用空间偏低"
      },
      "updatedText": {
        "type": "string",
        "description": "状态更新时间展示文本。",
        "sampleValue": "刚刚更新"
      }
    },
    "data": {
      "calendar": {
        "items": {
          "type": "array",
          "description": "查询到的日历日程列表。",
          "sampleValue": [
            {
              "entityName": "日程",
              "entityId": "calendar-demo-001",
              "title": "产品评审",
              "dtStart": "10:30",
              "dtEnd": "11:00"
            }
          ],
          "items": {
            "entityName": {
              "type": "string",
              "description": "日程内容类别。",
              "sampleValue": "日程"
            },
            "entityId": {
              "type": "string",
              "description": "日程项唯一标识符。",
              "sampleValue": "calendar-demo-001"
            },
            "title": {
              "type": "string",
              "description": "日程标题。",
              "sampleValue": "产品评审"
            },
            "dtStart": {
              "type": "string",
              "description": "日程开始时间，若为当天则为 HH:MM。",
              "sampleValue": "10:30"
            },
            "dtEnd": {
              "type": "string",
              "description": "日程结束时间，若为当天则为 HH:MM。",
              "sampleValue": "11:00"
            }
          }
        }
      }
    }
  },
  "assetCandidates": []
}

